"""Deterministic stratified local pilot; no networking or original writes."""
import duckdb,json,argparse
from pathlib import Path
p=argparse.ArgumentParser();p.add_argument('--source',required=True);p.add_argument('--out',type=Path,required=True);a=p.parse_args();c=duckdb.connect();c.execute('set threads=2');c.read_parquet(a.source).create_view('r')
sql="""WITH base AS (SELECT *,CASE WHEN category IS NULL THEN 'missing_category' WHEN latitude IS NULL OR longitude IS NULL THEN 'missing_coordinates' WHEN district_ar IS NULL THEN 'missing_district' WHEN lower(coalesce(company_status,'')) LIKE '%closed%' THEN 'closed' WHEN lower(category) LIKE '%hospital%' THEN 'healthcare' WHEN lower(category) LIKE '%education%' OR lower(category) LIKE '%school%' THEN 'education' WHEN lower(category) LIKE '%logistic%' THEN 'logistics' WHEN lower(category) LIKE '%information%' OR lower(category) LIKE '%law firm%' THEN 'professional' WHEN lower(category) LIKE '%coffee%' THEN 'coffee' WHEN lower(category) LIKE '%contract%' THEN 'contractors' WHEN lower(category) LIKE '%plumb%' THEN 'plumbing' ELSE 'other' END stratum FROM r WHERE lower(trim(city_en))='riyadh'), ranked AS (SELECT *,row_number() OVER(PARTITION BY stratum ORDER BY md5(poi_key)) rn FROM base) SELECT poi_key,name_ar,name_en,city_ar,city_en,region_ar,district_ar,district_en,latitude,longitude,category,secondary_category,category_l3,website,company_status,lifecycle_state,sources,stratum FROM ranked WHERE rn<=80 ORDER BY stratum,rn"""
cur=c.execute(sql);names=[d[0] for d in cur.description];rows=[dict(zip(names,r)) for r in cur.fetchall()];a.out.mkdir(parents=True,exist_ok=True);(a.out/'sample-raw.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2));print('sample',len(rows))
